import {createMatcher,validateRequest,localQuotes} from './matcher.mjs';

export const reasonText={busy:'Занят на выбранную дату',over_budget:'Стартовая цена выше бюджета',wrong_format:'Не указан этот формат',wrong_language:'Не указан нужный язык',too_short:'Длительность выше лимита',name_prefix:'Имя не начинается с нужной буквы',negative:'Описание противоречит пожеланию'};
const norm=s=>s.toLowerCase().replace(/ё/g,'е');
function negated(text,position){const clause=text.slice(0,position).split(/[,;.!?]/).at(-1);return /(?:^|[^\p{L}\p{N}_])(?:без|не|никаких|никакого|никакой|исключить|исключая)(?=$|[^\p{L}\p{N}_])/u.test(clause);}
export function parseBrief(text=''){const t=norm(text),items=[];for(const [key,label,stem] of [['calm','Спокойный стиль','спокойн'],['creative','Креативный подход','креативн'],['traditional','Традиционный формат','традиционн']]){const re=new RegExp('(?<![\\p{L}\\p{N}_])'+stem+'[\\p{L}\\p{N}_]*','gu');if([...t.matchAll(re)].some(m=>!negated(t,m.index)))items.push({key,label,kind:'preference'});}
for(const [language,word] of [['русский','русском'],['казахский','казахском'],['английский','английском']]){const re=new RegExp('(?<![\\p{L}\\p{N}_])(?:на|и|или)\\s+'+word+'(?![\\p{L}\\p{N}_])','gu');if([...t.matchAll(re)].some(m=>!negated(t,m.index)))items.push({key:'language',label:'Язык: '+language,value:language,kind:'condition'});}
for(const m of t.matchAll(/(?<![\p{L}\p{N}_])(?:без|никаких|исключить|исключая|не)\s+[^,;.!?]+/gu))items.push({key:'unwanted',label:m[0].trim(),kind:'preference'});
const prefix=t.match(/имя\s+начинается\s+(?:с\s+буквы|на\s+букву|на|с)\s*[«"']?([а-яa-z]+)/u);if(prefix&&!negated(t,prefix.index))items.push({key:'name_prefix',label:'Имя на «'+prefix[1].toUpperCase()+'»',value:prefix[1],kind:'condition'});return items;}
const evidencePatterns={calm:/спокой|интеллигент|ненавязчив|мягк|не напряжн/i,creative:/креатив|оригинальн|необыч|авторск/i,energetic:/энерги|динамич|драйв/i,traditional:/традиц|обряд/i,business:/делов|бизнес|форум|конференц/i};
export function assess(p,items){return items.map(item=>{let status='unknown',quote='';if(item.key==='language'){status=p.languages.includes(item.value)?'confirmed':'conflict';quote=p.languages.join(', ');}else if(item.key==='name_prefix'){status=norm(p.name).startsWith(item.value)?'confirmed':'conflict';quote=p.name;}else if(item.key==='unwanted'){status='unknown';
 }else{const re=evidencePatterns[item.key];const sentences=p.description.split(/(?<=[.!?])\s+|\n+|•/);const found=sentences.find(s=>re?.test(s));if(found){status='related';quote=found;}}
 return {...item,status,quote};});}
export function failures(p,r,items){const reasons=[];if(p.busy_dates.includes(r.date))reasons.push('busy');if(p.price_from_kzt>r.budget_kzt)reasons.push('over_budget');if(!p.event_formats.includes(r.event_format))reasons.push('wrong_format');if(r.language&&!p.languages.includes(r.language))reasons.push('wrong_language');if(r.duration_hours!==null&&p.max_hours!==null&&p.max_hours<r.duration_hours)reasons.push('too_short');if(items.some(i=>i.key==='name_prefix'&&!norm(p.name).startsWith(i.value)))reasons.push('name_prefix');return reasons;}
export function createPlanner(catalogue){const base=createMatcher(catalogue);
 function prepare(input){const parsed=parseBrief(input.brief||''),langs=parsed.filter(i=>i.key==='language').map(i=>i.value),notes=[];let language=input.language;if(language&&langs.length&&(langs.length!==1||norm(language.trim())!==langs[0]))notes.push('Для поиска используется язык из отдельного поля. В пожеланиях указан другой язык.');else if(!language&&langs.length===1){language=langs[0];notes.push('Язык взят из пожеланий.');}else if(!language&&langs.length>1)notes.push('В пожеланиях несколько языков. Выберите основной язык в отдельном поле.');const r=validateRequest({...input,language},catalogue);return {r,parsed,notes};}
 function compute(input){const {r,parsed,notes}=prepare(input);const source=base(r);const pool=catalogue.filter(p=>p.city===r.city&&p.categories.includes(r.category));const scoreOrder=source.allEligible||source.cards;const assessments=new Map(pool.map(p=>[p.id,assess(p,parsed)]));
 const eligible=scoreOrder.filter(p=>!failures(p,r,parsed).length);
 const selected=eligible.slice(0,3),quotes=localQuotes(selected,r);const cards=selected.map(p=>({...p,evidence_quote:quotes.get(p.id)}));const chosen=new Set(cards.map(p=>p.id));
 const excluded=pool.filter(p=>!chosen.has(p.id)).map(p=>({...p,failures:failures(p,r,parsed),assessment:assessments.get(p.id)})).sort((a,b)=>a.failures.length-b.failures.length||a.price_from_kzt-b.price_from_kzt);
 return {request:r,parsed,notes,cards,eligible:eligible.length,total:pool.length,excluded,assessments,status:!pool.length?'category_absent':cards.length?'matched':'no_eligible',alternatives:[]};}
 function alternatives(result){const r=result.request,items=result.parsed,baseline=result.eligible,candidates=[],pool=catalogue.filter(p=>p.city===r.city&&p.categories.includes(r.category));if(!pool.length||baseline>=3)return [];const count=request=>pool.filter(p=>!failures(p,request,items).length).length;
 function add(patch,kind,distance){const n=count({...r,...patch});if(n>baseline)candidates.push({patch,kind,count:n,distance});}
 const day=86400000,start=new Date(r.date+'T00:00:00Z').getTime(),dates=[];
 for(let offset=1;offset<=7;offset++)for(const sign of [1,-1]){const d=new Date(start+sign*offset*day).toISOString().slice(0,10);if(d>='2026-09-23'&&d<='2026-12-31')dates.push({d,offset});}
 for(const {d,offset} of dates){const before=candidates.length;add({date:d},'date',offset);if(candidates.length>before)break;}
 const prices=[...new Set(pool.map(p=>p.price_from_kzt))].filter(v=>v>r.budget_kzt&&v<=r.budget_kzt*1.25).sort((a,b)=>a-b);
 for(const price of prices){const n=candidates.length;add({budget_kzt:price},'budget',(price-r.budget_kzt)/r.budget_kzt);if(candidates.length>n)break;}
 const similar={'корпоратив':['конференция'],'конференция':['корпоратив'],'свадьба':['той'],'той':['свадьба','юбилей'],'юбилей':['день рождения','той'],'день рождения':['юбилей']};
 for(const format of similar[r.event_format]||[]){const n=candidates.length;add({event_format:format},'format',1);if(candidates.length>n)break;}
 const hours=r.duration_hours===null?[]:[...new Set(pool.map(p=>p.max_hours))].filter(v=>v!==null&&v<r.duration_hours&&v>=r.duration_hours-2).sort((a,b)=>b-a);
 for(const h of hours){const n=candidates.length;add({duration_hours:h},'duration',r.duration_hours-h);if(candidates.length>n)break;}
 if(!candidates.length){const changes=[dates.map(({d})=>({date:d})),prices.map(budget_kzt=>({budget_kzt})),hours.map(duration_hours=>({duration_hours})),(similar[r.event_format]||[]).map(event_format=>({event_format}))];let stop=false;for(let size=2;size<=4&&!stop;size++){function visit(index,patch,selected){if(selected===size){add(patch,'combined',Math.abs((new Date(patch.date||r.date)-new Date(r.date))/day));return;}for(let i=index;i<changes.length;i++)for(const change of changes[i])visit(i+1,{...patch,...change},selected+1);}visit(0,{},0);if(candidates.length)stop=true;}}
 const cost=a=>[Object.keys(a.patch).length,Math.abs((new Date(a.patch.date||r.date)-new Date(r.date))/day),(a.patch.budget_kzt||r.budget_kzt)-r.budget_kzt,(r.duration_hours||0)-(a.patch.duration_hours??r.duration_hours??0),a.patch.date&&a.patch.date<r.date?1:0];
 const seen=new Set();return candidates.filter(c=>{const key=JSON.stringify(c.patch);if(seen.has(key))return false;seen.add(key);return true;}).sort((a,b)=>{const x=cost(a),y=cost(b);for(let i=0;i<x.length;i++)if(x[i]!==y[i])return x[i]-y[i];return b.count-a.count;}).slice(0,3);
 }
 return input=>{const result=compute(input);result.alternatives=alternatives(result);return result;};
}
